'use strict';
// Read-only catalogue. The V5 material editor and its data are intentionally not consumed.
document.querySelector('.demo-banner').textContent='业务流程演示 V6 · 知识库索引查阅样板；尚未接入真实知识库，当前仅合成资料与模拟AI。';
let knowledgeQuery='',knowledgeType='all';
renderKnowledge=function(){
if(business()!=='gilligan'){$('#knowledge-page').innerHTML='<div class="empty">本Demo仅演示吉利根知识查阅，不读取Robert资料。</div>';return;}
$('#knowledge-page').innerHTML='<header class="page-header"><div><p class="eyebrow">知识库索引 · 查阅</p><h1>参考资料</h1></div><button id="return-creator" class="button ghost">返回新建内容</button></header><div class="notice"><strong>真实知识库索引尚未接入</strong><p>当前仅演示课程、书籍、成品、爆款的搜索与来源查阅，不是之前提取资料的真实搜索结果。无需在此新增或重新录入知识。</p></div><form id="knowledge-search" class="filter-row content-panel"><label>关键词<input id="knowledge-query" value="'+esc(knowledgeQuery)+'" placeholder="搜索资料标题或正文"></label><label>资料类型<select id="source-type"><option value="all">全部资料</option>'+Object.entries(sourceTypeNames).map(([k,v])=>'<option value="'+k+'" '+(knowledgeType===k?'selected':'')+'>'+v+'</option>').join('')+'</select></label><div class="button-row"><button class="button primary" type="submit">搜索</button><button id="knowledge-reset" class="button ghost" type="button">重置</button></div></form><p class="muted" id="knowledge-count"></p><div id="knowledge-results"></div><section><h2>已审文案参考</h2><p class="muted">由历史成稿标记和内容审核产生。这里只读查阅，不重复新增或审批。</p><div id="knowledge-team"></div></section>';
const results=F.retrieve(knowledgeQuery,knowledgeType,db.reviews),base=results.filter(x=>!x.reviewId),team=results.filter(x=>x.reviewId);
const cards=rows=>rows.map(x=>'<article class="source-card"><span class="tag">'+esc(sourceTypeNames[x.type])+'</span><h2>'+esc(x.title)+'</h2><p>'+esc(x.locator)+'</p><p class="muted">'+esc(x.usage)+'</p><button class="button ghost" data-knowledge-view="'+esc(x.id)+'">查看内容与来源</button></article>').join('');
$('#knowledge-count').textContent='匹配 '+base.length+' 条合成索引样例；非真实知识库覆盖数';$('#knowledge-results').innerHTML=base.length?cards(base):'<div class="empty">未找到匹配的合成样例，可重置或更换关键词；不代表真实知识库没有相关资料。</div>';$('#knowledge-team').innerHTML=team.length?cards(team):'<p class="muted">暂无匹配的已审文案参考。</p>';
$('#knowledge-search').onsubmit=e=>{e.preventDefault();knowledgeQuery=$('#knowledge-query').value.trim();knowledgeType=$('#source-type').value;renderKnowledge();};$('#knowledge-reset').onclick=()=>{knowledgeQuery='';knowledgeType='all';renderKnowledge();};$('#return-creator').onclick=()=>show('creator');$$('[data-knowledge-view]').forEach(b=>b.onclick=()=>openSource(results.find(x=>x.id===b.dataset.knowledgeView)));
};
